function graphMarkup(m=model(),marks=highlights,selection=selected){const paths=m.transitions.map(t=>{const a=m.states.find(s=>s.id===t.from),b=m.states.find(s=>s.id===t.to);if(!a||!b)return'';let d,lx,ly;const peers=m.transitions.filter(e=>e.from===t.from&&e.to===t.to),index=peers.indexOf(t);if(a===b){const h=65+index*30;d=`M ${a.x-18} ${a.y-20} C ${a.x-h} ${a.y-h-50}, ${a.x+h} ${a.y-h-50}, ${a.x+18} ${a.y-20}`;lx=a.x;ly=a.y-h-27;}else{const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,reverse=m.transitions.some(e=>e.from===t.to&&e.to===t.from),bend=t.bend??((index-(peers.length-1)/2)*35+(reverse?38:0)),cx=(a.x+b.x)/2-dy/len*bend,cy=(a.y+b.y)/2+dx/len*bend,sa=Math.atan2(cy-a.y,cx-a.x),sb=Math.atan2(cy-b.y,cx-b.x);d=`M ${a.x+Math.cos(sa)*29} ${a.y+Math.sin(sa)*29} Q ${cx} ${cy} ${b.x+Math.cos(sb)*33} ${b.y+Math.sin(sb)*33}`;lx=(a.x+2*cx+b.x)/4;ly=(a.y+2*cy+b.y)/4-9;}
 return`<g class="transition ${highlightEdges.includes(t.id)?'highlight':''}" data-transition="${t.id}"><path d="${d}" marker-end="url(#arrow)"/><path class="hit" d="${d}"/><text x="${lx}" y="${ly}" text-anchor="middle">${E(transitionLabel(t,m))}</text>${selection?.transition===t.id?`<circle class="control" data-bend="${t.id}" cx="${lx}" cy="${ly+9}" r="7"/>`:''}</g>`;}).join('');
 return`<defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#52665b"/></marker></defs>${paths}${m.states.map(s=>`<g class="state ${marks.includes(s.id)?'highlight':''} ${selection?.state===s.id?'selected':''}" data-state="${s.id}">${s.initial?`<path d="M ${s.x-65} ${s.y} H ${s.x-31}" stroke="#52665b" stroke-width="1.7" marker-end="url(#arrow)"/>`:''}<circle cx="${s.x}" cy="${s.y}" r="28"/>${s.final?`<circle cx="${s.x}" cy="${s.y}" r="23"/>`:''}<text x="${s.x}" y="${s.y}">${E(s.name)}${m.type==='moore'?'/'+E(s.output):s.block?' ▣':''}</text><text class="label" x="${s.x}" y="${s.y+46}">${E(s.label)}</text></g>`).join('')}${(m.notes||[]).map(n=>`<text class="note" x="${n.x}" y="${n.y}">${E(n.text)}</text>`).join('')}`;
}
