async function transitionForm(title,fields){
 const dialog=$('#dialog');let repeat=false;
 const continueEntry=e=>{
  if(e.key!=='Enter'||e.isComposing||e.ctrlKey||e.altKey||e.metaKey)return;
  if(!e.shiftKey&&!['INPUT','SELECT'].includes(e.target.tagName))return;
  e.preventDefault();
  if(!dialog.querySelector('form').reportValidity())return;
  repeat=e.shiftKey;dialog.close('ok');
 };
 dialog.addEventListener('keydown',continueEntry);
 try{
  const pending=form(title,fields);
  const hint=document.createElement('p');hint.className='hint';hint.textContent='Enter: apply · Shift+Enter: apply and add another transition between these states · Escape: cancel';$('#dialog-body').append(hint);
  return {values:await pending,repeat};
 }finally{dialog.removeEventListener('keydown',continueEntry);}
}
async function editTransition(id,from,to){
 while(true){
  const t=id===null?{from,to,read:''}:model().transitions.find(t=>t.id===id),fields=[];
  if(isTM())for(let i=0;i<model().tapes;i++){
   fields.push({name:'read'+i,label:`Tape ${i+1} · read (blank = □; ~ = any; !a = except a; a,b}x = capture on one tape)`,value:Array.isArray(t.read)?t.read[i]:t.read},{name:'write'+i,label:`Tape ${i+1} · write (blank = □; ~ = unchanged; variable = captured symbol)`,value:Array.isArray(t.write)?t.write[i]:t.write},{name:'move'+i,label:`Tape ${i+1} · move`,...tapeMoveChoices((Array.isArray(t.move)?t.move[i]:t.move)||'R',prefs.allowStay)});
  }else{
   fields.push({name:'read',label:'Input (empty = λ; ranges such as [0-9])',value:t.read});
   if(model().type==='pda')fields.push({name:'pop',label:'Pop from stack (empty = λ)',value:t.pop},{name:'push',label:'Push onto stack (leftmost symbol on top)',value:t.push});
   if(model().type==='mealy')fields.push({name:'output',label:'Output',value:t.output});
  }
  const {values:r,repeat}=await transitionForm('Transition '+t.from+' → '+t.to,fields);if(!r)return;
  const extra={};
  if(isTM()){
   extra.read=[];extra.write=[];extra.move=[];
   for(let i=0;i<model().tapes;i++){
    validateTapeRead(r['read'+i],model().tapes);
    if(tapeSymbol(r['write'+i]).length>1)throw Error('Tape read/write fields require one symbol or blank.');
    extra.read.push(tapeSymbol(r['read'+i]));extra.write.push(tapeSymbol(r['write'+i]));extra.move.push(r['move'+i]);
   }
  }else Object.keys(r).forEach(k=>extra[k]=A.empty(r[k]));
  checkpoint();if(id===null)A.edge(model(),from,to,extra.read,extra);else Object.assign(t,extra);
  draw();changed();if(!repeat)return;
  from=t.from;to=t.to;id=null;
 }
}
