 $('#shared-inputs').oninput=()=>{batchSession.inputs=$('#shared-inputs').value;};
 $('#batch-machines').querySelectorAll('[data-batch-machine]').forEach(el=>el.onchange=()=>{const m=docs[+el.dataset.batchMachine];el.checked?batchSession.selected.add(m):batchSession.selected.delete(m);});
 $('#batch-machines').querySelectorAll('[data-batch-edit]').forEach(el=>el.onclick=()=>{switchDocument(+el.dataset.batchEdit);tab='Editor';render();});
