 $('#content').innerHTML=`<div class="panel"><div class="split"><section><label class="field"><span>Grammar inputs · one per line</span><textarea id="grammar-batch-inputs" rows="7">${E(m.parseBatch??'λ\nab\naabb\naab')}</textarea></label><label class="field"><span>Load grammar inputs</span><input id="grammar-input-file" type="file" accept=".txt,.in,text/plain"></label><label class="field"><span>Batch parsing method</span><select id="grammar-batch-method"><option value="derive">Brute-force derivation</option><option value="cyk">CYK</option></select></label><div id="grammar-batch-actions" class="actions"></div></section><section id="grammar-batch-results" class="scroll"></section></div><h3>Selected derivation</h3><div id="parse-output" class="scroll"></div></div>`;
 $('#grammar-input-file').onchange=safe(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Choose inputs smaller than 5 MB.');$('#grammar-batch-inputs').value=parseInputs(await file.text()).join('\n');e.target.value='';});
 $('#grammar-batch-actions').append(button('Parse all inputs',()=>{m.parseBatch=$('#grammar-batch-inputs').value;persist();rows=parseGrammarBatch(m.productions,parseInputs(m.parseBatch),prefs.limit,$('#grammar-batch-method').value);$('#parse-output').replaceChildren();$('#grammar-batch-results').innerHTML='<table><caption>'+rows.length+' inputs</caption><tr><th>Input</th><th>Result</th><th>Details</th></tr>'+rows.map((r,i)=>`<tr><td>${E(r.input||'λ')}</td><td>${E(r.status)}${r.error?'<br>'+E(r.error):''}</td><td><button data-derivation="${i}">View ${r.method==='cyk'?'chart':'derivation'} ${i+1}</button></td></tr>`).join('')+'</table>';$('#grammar-batch-results').querySelectorAll('[data-derivation]').forEach(b=>b.onclick=()=>{const r=rows[+b.dataset.derivation];if(r.method==='cyk')showCYK(r);else showDerivation(r.rows||[]);});},'primary'));
