function showCYK(r){$('#parse-output').innerHTML=r.error?'<p class="error">'+E(r.error)+'</p>':'<h3>CYK chart · '+E(r.input||'λ')+'</h3>'+(!r.cells.length?'<p>Empty-word check: '+E(r.status)+'</p>':'<table><tr><th>Span length</th><th>Variable sets by starting position</th></tr>'+r.cells.map((row,i)=>'<tr><th>'+String(i+1)+'</th>'+row.slice(0,r.cells.length-i).map(cell=>'<td>'+E(cell.join(', ')||'∅')+'</td>').join('')+'</tr>').reverse().join('')+'</table>')+'<h3>Normalized grammar</h3><pre>'+E(G.grammarText(r.grammar))+'</pre>';if(!r.error){try{const tree=cykParseTree(r,r.input||'');if(tree){const pane=document.createElement('section');$('#parse-output').prepend(pane);drawParseTree(pane,tree);}}catch{}}}

function startGrammarSearch(m){
 grammarJob?.cancel();
 const job=m.format==='tokens-v1'?new TokenDerivationSearch(m,A.empty($('#grammar-word').value),{limit:prefs.limit}):new G.DerivationSearch(m.productions,A.empty($('#grammar-word').value),{limit:prefs.limit});grammarJob=job;
 const output=$('#parse-result');$('#parse-output').replaceChildren();let timer=null;
 const paint=()=>{
  if(grammarJob!==job||!output.isConnected)return;
  const r=job.result();output.innerHTML=`<div class="result ${E(r.status)}" role="status">${E(r.status.toUpperCase())} · ${r.count} forms discovered · ${r.expanded} expanded · ${r.work} search operations${r.reason==='length'?' · form-length bound reached':''}</div><div id="search-controls" class="actions"></div>`;
  const controls=$('#search-controls');
  if(job.status==='running')controls.append(button('Pause search',()=>{job.pause();clearTimeout(timer);paint();}));
  if(['paused','limit'].includes(job.status))controls.append(button('Resume search',()=>{job.resume(prefs.limit);paint();timer=setTimeout(tick,0);}));
  if(['running','paused','limit'].includes(job.status))controls.append(button('Cancel search',()=>{job.cancel();clearTimeout(timer);paint();}));
  if(job.status==='accepted')showDerivation(job.result().rows);
 };
 const tick=()=>{if(grammarJob!==job||!output.isConnected||job.status!=='running')return;job.chunk(250);paint();if(job.status==='running')timer=setTimeout(tick,0);};
 paneSuspend=()=>{job.pause();clearTimeout(timer);paint();};
 paint();timer=setTimeout(tick,0);
}

function manualDerivationPanel(){
 const session=new ManualDerivation(model().productions);
 toolbar([],'Choose a production and an occurrence to rewrite. Positions start at 1.');
 $('#content').innerHTML='<div class="panel"><h3>Build a derivation</h3><div id="rewrite-current" class="result mono"></div><label class="field"><span>Production</span><select id="rewrite-rule"></select></label><label class="field"><span>Occurrence in the current form</span><select id="rewrite-position"></select></label><div id="rewrite-actions" class="actions"></div><div id="rewrite-history" class="scroll"></div></div>';
 $('#rewrite-rule').innerHTML=session.productions.map((p,i)=>`<option value="${i}">${i+1}. ${E(p.left)} → ${E(p.right||'λ')}</option>`).join('');
 const occurrences=()=>{
  const positions=session.occurrences(+$('#rewrite-rule').value);
  $('#rewrite-position').innerHTML=positions.length?positions.map(i=>`<option value="${i}">Position ${i+1}</option>`).join(''):'<option value="">No matching occurrence</option>';
  $('#rewrite-apply').disabled=!positions.length;
 };
 const paint=()=>{
  $('#rewrite-current').textContent=session.word||'λ';
  $('#rewrite-history').innerHTML='<table><tr><th>Step</th><th>Form</th><th>Production</th><th>Position</th></tr>'+session.rows.map((r,i)=>`<tr><td>${i}</td><td class="mono">${E(r.word||'λ')}</td><td>${E(r.action)}</td><td>${r.position===undefined?'—':r.position+1}</td></tr>`).join('')+'</table>';
  $('#rewrite-undo').disabled=session.rows.length===1;occurrences();
 };
 const apply=button('Apply production',()=>{session.apply(+$('#rewrite-rule').value,+$('#rewrite-position').value);paint();},'primary');apply.id='rewrite-apply';
 const undo=button('Undo derivation step',()=>{session.undo();paint();});undo.id='rewrite-undo';
 $('#rewrite-actions').append(apply,undo,button('Restart derivation',()=>{session.reset();paint();}));
 $('#rewrite-rule').onchange=occurrences;paint();
}

async function convertPDA(m){
 const r=await form('Convert PDA to context-free grammar',[{name:'acceptance',label:'PDA acceptance',value:'final',options:[['final','Final state after consuming input'],['empty','Empty stack after consuming input']]}]);
 if(!r)return;const g=pdaToGrammar(m,{acceptance:r.acceptance});g.conversion.source=A.clone(m);add(g);
}
function tokenGrammarPanel(){
 const m=model(),conversion=m.conversion;
 if(tab==='Parse'){
  toolbar([],conversion?.kind==='turing-to-grammar'?'Final-state acceptance. Limits are inconclusive; general grammar search supports pause and resume.':'Search the generated grammar. Limits are inconclusive; resume to continue.');
  $('#content').innerHTML='<div class="panel split"><section><label class="field"><span>Input string</span><input id="grammar-word" value="ab"></label><div id="token-parse-actions" class="actions"></div><div id="source-check"></div><div id="parse-result"></div></section><div id="parse-output" class="scroll"></div></div>';
  if(conversion?.kind==='turing-to-grammar')$('#grammar-word').value=(conversion.alphabet[0]||'').repeat(2);
  $('#token-parse-actions').append(button('Parse generated grammar',()=>{
   const word=A.empty($('#grammar-word').value);
   if(conversion?.source){const result=simulate(conversion.source,word,{...prefs,acceptance:conversion.acceptance,finalTransitions:false});$('#source-check').textContent='Source '+(conversion.kind==='turing-to-grammar'?'Turing machine':'PDA')+': '+result.status.toUpperCase()+' · '+(conversion.acceptance==='empty'?'empty-stack':'final-state')+' acceptance';}
   if(conversion?.kind==='turing-to-grammar'){
    grammarJob?.cancel();grammarJob=null;
    const r=deriveTuringGrammar(m,word,{limit:prefs.limit});$('#parse-result').innerHTML=`<div class="result ${E(r.status)}">${E(r.status.toUpperCase())} · ${r.count} grammar configurations${r.reason==='outside-alphabet'?' · input contains a symbol outside the chosen alphabet':''}</div>`;showDerivation(r.rows);
   }else startGrammarSearch(m);
  },'primary'));
  if(conversion?.kind==='turing-to-grammar'){
   $('#token-parse-actions').append(button('General grammar search',()=>{$('#source-check').textContent='General rewrite search: initialization and simulation rules may interleave.';startGrammarSearch(m);}));
   $('#parse-result').textContent='Parse generated grammar fixes the input-generation phase, then searches actual transition productions. General grammar search explores unrestricted rewrites and can be much larger.';
  }return;
 }
 toolbar([['Parse a word',()=>{tab='Parse';render();}],['Export grammar JSON',()=>save()],['Export readable grammar',()=>download(tokenGrammarText(m),(m.name||'grammar')+'.txt')]],'Named variables are atomic. JSON preserves their identities; readable text is for reference.');
 const states=new Map((conversion?.states||[]).map(s=>[s.id,s.name+' (#'+s.id+')']));
 $('#content').innerHTML='<div class="panel"><h3>Named-variable grammar</h3>'+(conversion?.kind==='pda-to-cfg'?`<p>Converted using ${conversion.acceptance==='empty'?'empty-stack':'final-state'} acceptance. ${conversion.generated} productions constructed; ${conversion.retained} retained after removing useless and duplicate rules.</p><p>A variable ⟨[p,A,q]⟩ generates the input strings that remove stack symbol A while moving from state p to q, preserving the stack below A. Start is the grammar start variable. Extra states normalize stack operations and acceptance.</p>`:'')+(conversion?.kind==='turing-to-grammar'?`<p>Single tape · final-state acceptance · input alphabet: ${E(conversion.alphabet.join(', ')||'empty')}. ${conversion.productionCount} productions.</p><p>Each cell variable stores [original input, current tape]. State variables mark the head. Boundary rules extend blank tape; cleanup emits the original input only after a final state is reached. The saved source machine is available for comparison in Parse.</p>`:'')+'<pre>'+E(tokenGrammarText(m))+'</pre>'+(conversion?.legend?'<h3>Variable legend</h3><table><tr><th>Variable</th><th>From state</th><th>Stack symbol</th><th>To state</th></tr>'+Object.entries(conversion.legend).map(([name,v])=>`<tr><td>${E(name)}</td><td>${E(states.get(v.from))}</td><td>${E(v.stack)}</td><td>${E(states.get(v.to))}</td></tr>`).join('')+'</table>':'')+'</div>';
}

async function convertTuring(m){
 const candidates=[...new Set(m.transitions.flatMap(t=>Array.isArray(t.read)?t.read:[t.read]).filter(c=>c&&c.length===1&&!['~','□','λ','ε'].includes(c)))];
 const r=await form('Convert Turing machine to unrestricted grammar',[{name:'alphabet',label:'Input alphabet (one character per symbol; final-state acceptance)',value:candidates.join('')}]);
 if(r)add(turingToGrammar(m,{alphabet:[...r.alphabet]}));
}

function drawParseTree(container,root,{activeStep=-1,orientation:initialOrientation='normal',onOrientation=()=>{}}={}){
 container.innerHTML='<h3>Parse tree</h3><label class="field"><span>Tree orientation</span><select class="tree-orientation"><option value="normal">Normal</option><option value="inverted">Inverted</option></select></label><div class="tree-drawing scroll"></div>';
 const orientation=container.querySelector('select'),target=container.querySelector('.tree-drawing');orientation.value=initialOrientation;
 const paint=()=>{
  const layout=layoutParseTree(root,orientation.value==='inverted'),byId=new Map(layout.nodes.map(n=>[n.id,n]));
  target.innerHTML=`<svg role="img" aria-label="${orientation.value==='inverted'?'Inverted':'Normal'} parse tree" width="${layout.width}" height="${layout.height}" viewBox="0 0 ${layout.width} ${layout.height}">${layout.edges.map(e=>{const a=byId.get(e.from),b=byId.get(e.to);return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#718579"/>`;}).join('')}${layout.nodes.map(n=>`<g data-tree-node="${n.id}" class="${n.steps?.includes(activeStep)?'parse-active':''}"><title>${E(n.label)}</title><rect x="${n.x-40}" y="${n.y-17}" width="80" height="34" rx="10" fill="${n.kind==='variable'?'#d4eee2':'#fff1bd'}" stroke="#718579"/><text x="${n.x}" y="${n.y+5}" text-anchor="middle" font-size="13" fill="#183c2c">${E(n.label.length>11?n.label.slice(0,10)+'…':n.label)}</text></g>`).join('')}</svg>`;
 };orientation.onchange=()=>{onOrientation(orientation.value);paint();};paint();
}

function drawDerivationGraph(container,graph,activeStep=-1){
 const selected=graph.rewrites[activeStep],activeNodes=new Set(selected?[...selected.parents,...selected.children]:[]);
 const layout=layoutDerivationGraph(graph),byId=new Map(layout.nodes.map(n=>[n.id,n]));
 const line=(a,b,style='')=>`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#718579" ${style}/>`;
 container.innerHTML=`<h3>Unrestricted derivation graph</h3><p class="hint">Each diamond is one rewrite. All connected parent symbols are replaced together. Dashed lines carry unchanged symbols to the next form; λ marks an empty replacement.</p><div class="derivation-drawing scroll"><svg role="img" aria-label="Unrestricted derivation graph" width="${layout.width}" height="${layout.height}" viewBox="0 0 ${layout.width} ${layout.height}">${layout.edges.map(e=>line(byId.get(e.from),byId.get(e.to),'stroke-dasharray="4 5" opacity="0.4"')).join('')}${layout.rewrites.map(r=>r.parents.map(id=>line(byId.get(id),r)).join('')+r.children.map(id=>line(r,byId.get(id))).join('')+`<g data-rewrite-step="${r.step}" class="${r.step===activeStep?'parse-active':''}"><title>${E(r.action)}</title><path d="M ${r.x} ${r.y-9} l 9 9 l -9 9 l -9 -9 Z" fill="#24715a"/><text x="${r.x+15}" y="${r.y+4}" font-size="12">${r.step+1}</text></g>`).join('')}${layout.nodes.map(n=>`<g data-graph-node="${n.id}" class="${activeNodes.has(n.id)?'parse-active':''}"><title>${E(n.symbol.name)}</title><rect x="${n.x-40}" y="${n.y-17}" width="80" height="34" rx="8" fill="${n.symbol.kind==='variable'?'#d4eee2':'#fff1bd'}" stroke="#718579"/><text x="${n.x}" y="${n.y+5}" text-anchor="middle" font-size="13">${E(n.symbol.name.length>11?n.symbol.name.slice(0,10)+'…':n.symbol.name)}</text></g>`).join('')}</svg></div>`;
}

