 if(session.mode==='items'){lrItemsPanel(session);return;}if(session.mode==='ll'){llExercisePanel(session);return;}if(session.mode==='lr'){lrExercisePanel(session);return;}
 const exercise=session.firstFollow;session.selected??=exercise.cells[0].key;
 toolbar([['LR item construction',()=>{session.mode='items';grammarExercisePanel();}],['LL table exercise',()=>{session.mode='ll';grammarExercisePanel();}],['LR table exercise',()=>{session.mode='lr';grammarExercisePanel();}]],'Build FIRST and FOLLOW sets. Select a cell to check it or request help.');
