 const refresh=()=>fields().forEach(el=>{el.value=exercise.answers[el.dataset.lrCell];el.removeAttribute('aria-invalid');});
 const report=()=>{const results=exercise.checkAll(),bad=results.filter(r=>!r.correct);fields().forEach(el=>el.setAttribute('aria-invalid',String(!results.find(r=>r.key===el.dataset.lrCell).correct)));$('#lr-feedback').textContent=bad.length?bad.map(r=>r.key+': '+(r.error||'Missing '+(r.missing.join(', ')||'none')+'; unexpected '+(r.extra.join(', ')||'none'))).join(' | '):'All table entries are correct.'+(exercise.data.conflicts.length?' Choose each conflict action explicitly before parsing.':'');};
 const invalidate=()=>{$('#parse-output').replaceChildren();$('#lr-parse-result').textContent='';};
 fields().forEach(el=>{el.onfocus=()=>select(el.dataset.lrCell);el.oninput=()=>{exercise.answers[el.dataset.lrCell]=el.value;el.removeAttribute('aria-invalid');$('#lr-feedback').textContent='Answer changed; check again when ready.';invalidate();};});
 $('#content').querySelectorAll('[data-lr-choice]').forEach(el=>el.onchange=()=>{if(el.value)exercise.resolve(el.dataset.lrChoice,el.value);else delete exercise.choices[el.dataset.lrChoice];invalidate();});
 $('#lr-exercise-actions').append(button('Check LR table',report,'primary'),button('Do selected',()=>{exercise.fill(session.lrSelected);refresh();invalidate();}),button('Step',()=>{const key=exercise.step();refresh();invalidate();if(key){select(key);$('#lr-feedback').textContent='Filled '+key;}else report();}),button('Do all',()=>{exercise.fillAll();refresh();invalidate();report();}),button('Reset table',()=>{exercise.reset();lrExercisePanel(session);}));
 $('#lr-exercise-parse').onclick=()=>{try{const r=exercise.parse(A.empty($('#lr-exercise-input').value));$('#lr-parse-result').textContent=r.status.toUpperCase();showDerivation(r.rows,{table:r.table,method:'lrParse'});}catch(e){$('#lr-parse-result').textContent=e.message;$('#parse-output').replaceChildren();}};
 select(session.lrSelected);
