function lrItemsPanel(session){
 session.items??=new LRItemsExercise(model().productions);const ex=session.items;session.itemState??=0;
 toolbar([['FIRST / FOLLOW exercise',()=>{session.mode='first';grammarExercisePanel();}],['LR table exercise',()=>{session.mode='lr';grammarExercisePanel();}]],'Construct LR(0) item sets and the goto diagram. State numbers follow the canonical construction.');
 $('#content').innerHTML=`<div class="panel"><h3>LR item construction</h3><p>Use rule:dot pairs, separated by spaces. Rule 0 is the augmented start rule. Dot positions count symbols from 0. State slots are supplied; fill their items and connect them. Blank transitions mean no edge.</p><ol start="0">${ex.data.rules.map(r=>`<li>${E(r.left)} → ${E(r.right||'λ')}</li>`).join('')}</ol><div class="split"><div><label class="field"><span>State to edit</span><select id="items-state">${ex.answers.map((_,i)=>`<option value="${i}" ${i===session.itemState?'selected':''}>${i}</option>`).join('')}</select></label><label class="field"><span>Items (rule:dot)</span><textarea id="items-answer" rows="4">${E(ex.answers[session.itemState])}</textarea></label><pre id="items-readable"></pre><div id="items-actions" class="actions"></div></div><div><h4>Connect selected state</h4><label class="field"><span>Goto symbol</span><select id="items-symbol">${ex.symbols.map(c=>`<option value="${E(c)}">${E(c)}</option>`).join('')}</select></label><label class="field"><span>Target state (blank removes edge)</span><input id="items-target"></label><div id="items-edge-actions" class="actions"></div></div></div><div id="items-feedback" role="status"></div><div id="items-diagram" class="scroll"></div></div>`;
 const feedback=text=>$('#items-feedback').textContent=text;
 const readable=()=>{try{$('#items-readable').textContent=ex.parse(ex.answers[session.itemState]).map(i=>ex.itemText(i)).join('\n');}catch(e){$('#items-readable').textContent=e.message;}};
 const refresh=()=>{$('#items-answer').value=ex.answers[session.itemState];$('#items-target').value=ex.edges[session.itemState+','+$('#items-symbol').value]??'';readable();draw();};
 const draw=()=>{const width=800,height=Math.max(160,Math.ceil(ex.answers.length/4)*150+30),xy=i=>[80+(i%4)*195,90+Math.floor(i/4)*150];$('#items-diagram').innerHTML=`<svg viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="Entered LR item diagram"><defs><marker id="lr-item-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="currentColor"/></marker></defs>${Object.entries(ex.edges).map(([key,to])=>{const comma=key.indexOf(','),from=Number(key.slice(0,comma)),symbol=key.slice(comma+1),[x,y]=xy(from),[u,v]=xy(to);return from===to?`<path d="M${x-15},${y-20} C${x-65},${y-85} ${x+65},${y-85} ${x+15},${y-20}" fill="none" stroke="currentColor" marker-end="url(#lr-item-arrow)"/><text x="${x}" y="${y-65}" text-anchor="middle">${E(symbol)}</text>`:`<path d="M${x},${y+25} Q${(x+u)/2},${(y+v)/2+65} ${u},${v+28}" fill="none" stroke="currentColor" marker-end="url(#lr-item-arrow)"/><text x="${(x+u)/2}" y="${(y+v)/2+48}" text-anchor="middle">${E(symbol)}</text>`;}).join('')}${ex.answers.map((_,i)=>{const[x,y]=xy(i);return `<g><circle cx="${x}" cy="${y}" r="27" fill="${i===session.itemState?'#fff1a8':'#edf4ff'}" stroke="${ex.checkState(i).correct?'#16815e':'#607080'}"/><text x="${x}" y="${y+5}" text-anchor="middle" fill="#182534">${i}</text></g>`;}).join('')}</svg><p>Green outlines mark correct item sets. The diagram shows entered transitions, including mistakes until corrected.</p><ul>${Object.entries(ex.edges).map(([key,to])=>`<li>${E(key)} → ${to}</li>`).join('')}</ul>`;};
 $('#items-state').onchange=()=>{session.itemState=Number($('#items-state').value);refresh();feedback('');};
 $('#items-answer').oninput=()=>{ex.answers[session.itemState]=$('#items-answer').value;readable();draw();feedback('');};
 $('#items-symbol').onchange=()=>{$('#items-target').value=ex.edges[session.itemState+','+$('#items-symbol').value]??'';};
 const act=fn=>()=>{try{fn();refresh();}catch(e){feedback(e.message);}};
 $('#items-actions').append(button('Check state',()=>{const r=ex.checkState(session.itemState);feedback(r.correct?'Item set is correct.':r.error||`Missing: ${ex.format(r.missing)||'none'}; extra: ${ex.format(r.extra)||'none'}`);}),button('Closure',act(()=>{ex.closeState(session.itemState);feedback('Applied closure to your entered items.');})),button('Do selected',act(()=>{ex.fillState(session.itemState);feedback('Filled selected item set.');})),button('Step',act(()=>feedback(ex.step()))),button('Do all',act(()=>{ex.fillAll();feedback('Construction is correct.');})),button('Check construction',()=>{const r=ex.check();feedback(r.correct?'Construction is correct.':`${r.states.filter(s=>!s.correct).length} incorrect item sets; ${r.missing.length} missing or incorrect transitions; ${r.extra.length} extra or incorrect transitions.`);}),button('Reset construction',()=>{ex.reset();lrItemsPanel(session);}));
 $('#items-edge-actions').append(button('Set transition',act(()=>{ex.connect(session.itemState,$('#items-symbol').value,$('#items-target').value.trim());feedback('Transition updated.');})),button('Do goto',act(()=>{const target=ex.doGoto(session.itemState,$('#items-symbol').value);feedback(target===null?'Goto is empty.':`Goto added state ${target} and its closed item set.`);})));refresh();
}

function subsetPanel(){
 const source=model(),signature=JSON.stringify([source.states,source.transitions]);let session=subsetExercises.get(source);
 if(!session||session.signature!==signature){session={signature,exercise:new SubsetExercise(source)};subsetExercises.set(source,session);}const ex=session.exercise,jobs=ex.jobs();
 toolbar([['Export completed DFA',()=>add(ex.export()),'primary'],['Reset construction',()=>{ex.reset();subsetPanel();}]],'Build each DFA state as an epsilon-closed subset of the source states.');
 $('#content').innerHTML=`<div class="panel"><h3>Guided NFA → DFA</h3><p>The initial subset is the λ-closure of the source initial state. For each symbol, find all destinations, then take their λ-closure. A subset is final if it contains any final source state. Empty targets are checked but omitted from this partial DFA.</p><details><summary>Source states and normalized transitions</summary><p>Ranges and multi-symbol labels are expanded before the exercise. Use the numeric IDs below, including any added intermediate states.</p><ul>${ex.source.states.map(s=>`<li>${s.id}: ${E(s.name)}${s.initial?' · initial':''}${s.final?' · final':''}</li>`).join('')}</ul><pre>${E(ex.source.transitions.map(t=>`${t.from} —${t.read||'λ'}→ ${t.to}`).join('\n'))}</pre></details><table><tr><th>DFA state</th><th>Source subset</th><th>Final</th></tr>${ex.subsets.map((set,i)=>`<tr><td>q${i}</td><td>{${set.join(', ')}}</td><td>${ex.output.states[i].final?'Yes':'No'}</td></tr>`).join('')}</table>${jobs.length?`<label class="field"><span>Pending transition</span><select id="subset-job">${jobs.map((j,i)=>`<option value="${i}">q${j.from} on ${E(j.symbol)}</option>`).join('')}</select></label><label class="field"><span>Destination subset (source state IDs, or ∅)</span><input id="subset-answer"></label><div id="subset-actions" class="actions"></div>`:'<p>All reachable subset transitions are complete. Export the DFA to edit, save or simulate it.</p>'}<div id="subset-feedback" role="status"></div><svg id="subset-graph" viewBox="0 0 900 520" aria-label="DFA construction">${graphMarkup(ex.output,[],null)}</svg></div>`;
 if(!jobs.length)return;const job=()=>jobs[Number($('#subset-job').value)],update=text=>{subsetPanel();$('#subset-feedback').textContent=text;};
 $('#subset-actions').append(button('Check and add',()=>{const j=job(),r=ex.submit(j.from,j.symbol,$('#subset-answer').value);if(r.correct)update(r.empty?'Correct: empty destination; no edge added.':'Correct: subset and transition added.');else $('#subset-feedback').textContent=`Not yet correct. Missing IDs: ${r.missing.join(', ')||'none'}; extra IDs: ${r.extra.join(', ')||'none'}.`;},'primary'),button('Do transition',()=>{const j=job();ex.submit(j.from,j.symbol,ex.expected(j.from,j.symbol).join(','));update('Completed selected transition.');}),button('Expand selected state',()=>{ex.expand(job().from);update('Completed all symbols from the selected state.');}),button('Complete construction',()=>{ex.finish();update('All reachable subset transitions are complete.');}));
}

function minimizationPanel(){
 const source=model(),signature=JSON.stringify([source.states,source.transitions]);let session=minimizationExercises.get(source);if(!session||session.signature!==signature){session={signature,exercise:new MinimizationExercise(source)};minimizationExercises.set(source,session);}const ex=session.exercise,groups=ex.groups(),stable=!ex.jobs().length;
 toolbar([['Reset minimization',()=>{ex.reset();minimizationPanel();}]],'Refine final/nonfinal partitions, then construct the quotient DFA.');
 const tree=id=>{const n=ex.nodes[id];return `<li><span>${E(n.reason)}: {${n.ids.join(', ')}}</span>${n.children.length?'<ul>'+n.children.map(tree).join('')+'</ul>':''}</li>`;};
 $('#content').innerHTML=`<div class="panel"><h3>Guided DFA minimization</h3><p>The source is first converted to a reachable, complete DFA (including a trap state if needed). The IDs below belong to that DFA. Split a partition by the destination partitions reached on one symbol. States that remain together have equivalent behavior.</p><details><summary>Working DFA transitions and source subsets</summary><table><tr><th>State</th><th>Source subset</th><th>Flags</th>${ex.alphabet.map(c=>`<th>${E(c)}</th>`).join('')}</tr>${ex.source.states.map(s=>`<tr><td>${s.id}</td><td>${E(s.label)}</td><td>${s.initial?'Initial ':''}${s.final?'Final':''}</td>${ex.alphabet.map(c=>`<td>${ex.target(s.id,c)}</td>`).join('')}</tr>`).join('')}</table></details><h4>Partition tree</h4><ul aria-label="Minimization partition tree">${tree(0)}</ul><p>Current partitions: ${groups.map((g,i)=>`P${i} = {${g.join(', ')}}`).join('; ')}</p>${stable?'<p>Stable partition: no symbol distinguishes states within a group.</p>':`<label class="field"><span>Partition to split</span><select id="min-group">${groups.map((g,i)=>`<option value="${i}">P${i}: {${g.join(', ')}}</option>`).join('')}</select></label><label class="field"><span>Distinguishing symbol</span><select id="min-symbol">${ex.alphabet.map(c=>`<option value="${E(c)}">${E(c)}</option>`).join('')}</select></label><label class="field"><span>New groups (IDs separated by commas; groups separated by |)</span><input id="min-answer" placeholder="0 | 1,2"></label>`}<div id="min-actions" class="actions"></div><div id="min-feedback" role="status"></div><div id="min-result"></div></div>`;
 const update=text=>{minimizationPanel();$('#min-feedback').textContent=text;};const actions=$('#min-actions');
 if(!stable)actions.append(button('Check split',()=>{const correct=ex.split(Number($('#min-group').value),$('#min-symbol').value,$('#min-answer').value);if(correct)update('Correct split added to the partition tree.');else $('#min-feedback').textContent='Incorrect grouping. Put states together exactly when this symbol leads to the same current partition.';},'primary'),button('Do selected split',()=>{const i=Number($('#min-group').value),c=$('#min-symbol').value;ex.split(i,c,ex.expected(i,c).map(g=>g.join(',')).join('|'));update('Selected split added.');}),button('Step refinement',()=>{ex.step();update('One partition refined.');}),button('Complete refinement',()=>{ex.finish();update('Partition refinement is complete.');}));
 actions.append(button('Undo split',()=>{const changed=ex.undo();update(changed?'Last split undone.':'No split to undo.');}));
 if(stable){actions.append(button('Build result states',()=>{ex.beginResult();update('One result state created per partition.');}));}
 if(ex.result){const jobs=ex.resultJobs();$('#min-result').innerHTML=`<h4>Construct the minimal DFA</h4><p>Each qN represents PN. Initial and final flags follow the member states.</p>${jobs.length?`<label class="field"><span>Result transition</span><select id="min-job">${jobs.map((j,i)=>`<option value="${i}">q${j.from} on ${E(j.symbol)}</option>`).join('')}</select></label><label class="field"><span>Destination partition number</span><input id="min-target"></label>`:'<p>All result transitions are complete.</p>'}<div id="min-result-actions" class="actions"></div><svg viewBox="0 0 900 520" aria-label="Minimal DFA construction">${graphMarkup(ex.result,[],null)}</svg>`;const controls=$('#min-result-actions');if(jobs.length)controls.append(button('Check transition',()=>{const j=jobs[Number($('#min-job').value)];if(ex.connect(j.from,j.symbol,$('#min-target').value.trim()))update('Correct result transition added.');else $('#min-feedback').textContent='Incorrect destination. Find the partition containing the destination of any member state.';}),button('Complete result transitions',()=>{ex.completeResult();update('Result transitions complete.');}));controls.append(button('Export minimal DFA',()=>add(ex.export()),'primary'));}
}

function regexEliminationPanel(){
 const source=model(),signature=JSON.stringify([source.states,source.transitions]);let session=regexEliminations.get(source);if(!session||session.signature!==signature){session={signature,exercise:new RegexElimination(source)};regexEliminations.set(source,session);}const ex=session.exercise,candidates=ex.candidates();
 toolbar([['Undo elimination',()=>{ex.undo();regexEliminationPanel();}],['Reset elimination',()=>{ex.reset();regexEliminationPanel();}]],'Choose any remaining original state. Each step preserves the accepted language.');
 $('#content').innerHTML=`<div class="panel"><h3>FA → regular expression</h3><p>Start and End are added with λ edges. Parallel transitions are combined with union (+). Eliminating state k updates each remaining edge using R(i,j) + R(i,k)(R(k,k))*R(k,j). Missing edges represent ∅. The graph below uses regular-expression labels, not ordinary single-symbol transitions.</p><p>Elimination order: ${ex.order.map(id=>E(ex.name(id))).join(' → ')||'none yet'}</p>${candidates.length?`<label class="field"><span>State to eliminate</span><select id="eliminate-state">${candidates.map(id=>`<option value="${id}">${E(ex.name(id))} (ID ${id})</option>`).join('')}</select></label>`:`<label class="field"><span>Resulting expression</span><textarea readonly rows="4">${E(ex.expression())}</textarea></label>`}<div id="elimination-actions" class="actions"></div><h4>Current transition graph</h4><div class="scroll"><svg viewBox="0 0 900 520" aria-label="Regular expression elimination graph">${graphMarkup(ex.graph(),[],null)}</svg></div><details open><summary>Current edge expressions</summary><table><tr><th>From</th><th>To</th><th>Expression</th></tr>${Object.entries(ex.labels).map(([key,label])=>{const [a,b]=key.split(',').map(Number);return`<tr><td>${E(ex.name(a))}</td><td>${E(ex.name(b))}</td><td class="regex-expression">${E(label)}</td></tr>`;}).join('')}</table></details>${ex.changes.length?`<h4>Edges changed by the last elimination</h4><table><tr><th>Edge</th><th>Previous</th><th>Via eliminated state</th><th>New expression</th></tr>${ex.changes.map(c=>`<tr><td>${E(ex.name(c.from))} → ${E(ex.name(c.to))}</td><td class="regex-expression">${E(c.before)}</td><td class="regex-expression">${E(c.via)}</td><td class="regex-expression">${E(c.after)}</td></tr>`).join('')}</table>`:''}</div>`;
 const actions=$('#elimination-actions');if(candidates.length)actions.append(button('Eliminate selected state',()=>{ex.eliminate(Number($('#eliminate-state').value));regexEliminationPanel();},'primary'),button('Complete elimination',()=>{ex.finish();regexEliminationPanel();}));else actions.append(button('Open resulting expression',()=>add(ex.export()),'primary'),button('Download expression',()=>download(ex.expression(),source.name+'-expression.txt','text/plain')));
}

function regexConstructionPanel(){
 const source=model(),signature=source.expression;let session=regexConstructions.get(source);if(!session||session.signature!==signature){session={signature,exercise:new RegexConstruction(signature)};regexConstructions.set(source,session);}const ex=session.exercise,pending=ex.pending();
 toolbar([['Undo decomposition',()=>{ex.undo();regexConstructionPanel();}],['Reset construction',()=>{ex.reset();regexConstructionPanel();}]],'Replace expression edges with union, concatenation and repetition fragments.');
 const tree=n=>`<li>${E(n.kind)}: ${E(regexTreeText(n))}${n.child?'<ul>'+tree(n.child)+'</ul>':n.left?'<ul>'+tree(n.left)+tree(n.right)+'</ul>':''}</li>`;
 const explanations={symbol:'Keep a single-symbol transition.',epsilon:'Create an empty-input transition.',empty:'Remove the edge: the empty language has no path.',union:'Create parallel branches for the two alternatives.',concat:'Add an intermediate state and connect the two expressions in order.',star:'Add an empty bypass, a child fragment and an empty repetition loop.'};
 $('#content').innerHTML=`<div class="panel"><h3>Interactive regex → NFA</h3><p>Choose any unfinished edge to decompose. Union (+) branches; concatenation connects fragments; star (*) adds repetition and an empty bypass. Compound labels are temporary: export is available only after every edge is resolved.</p><details><summary>Expression decomposition tree</summary><ul>${tree(ex.root)}</ul></details>${pending.length?`<label class="field"><span>Expression edge to decompose</span><select id="regex-fragment">${pending.map(t=>`<option value="${t.id}">q${t.from} → q${t.to}: ${E(t.read)} · ${E(t.expressionNode.kind)}</option>`).join('')}</select></label>`:'<p>Construction complete. Every remaining transition reads one symbol or λ.</p>'}<div id="regex-build-actions" class="actions"></div><div role="status">${ex.steps.length?E(explanations[ex.steps.at(-1).kind]):'Begin with one expression edge between the initial and final states.'}</div><svg viewBox="0 0 900 520" aria-label="Regex NFA construction">${graphMarkup(ex.model,[],null)}</svg><h4>Decomposition steps</h4><ol>${ex.steps.map(t=>`<li>q${t.from} → q${t.to}: ${E(t.expression)} — ${E(explanations[t.kind])}</li>`).join('')}</ol></div>`;
 const actions=$('#regex-build-actions');if(pending.length)actions.append(button('Decompose selected edge',()=>{ex.expand(Number($('#regex-fragment').value));regexConstructionPanel();},'primary'),button('Step construction',()=>{ex.step();regexConstructionPanel();}),button('Complete NFA',()=>{ex.finish();regexConstructionPanel();}));else actions.append(button('Open constructed NFA',()=>add(ex.export()),'primary'));
}

function faGrammarPanel(){
 const source=model(),signature=JSON.stringify([source.states,source.transitions]);let session=faGrammarExercises.get(source);if(!session||session.signature!==signature){session={signature,exercise:new FAGrammarExercise(source)};faGrammarExercises.set(source,session);}const ex=session.exercise;session.selected??=ex.jobs[0]?.key;
 toolbar([['Open completed grammar',()=>add(ex.export()),'primary'],['Reset productions',()=>{ex.reset();faGrammarPanel();}]],'Write one production per normalized transition and one empty production per final state.');
 $('#content').innerHTML=`<div class="panel"><h3>Guided FA → grammar</h3><p>A state with ID n becomes the named variable Qn. A transition p —a→ q produces Qp → a Qq. A λ transition produces Qp → Qq. A final state produces Qp → λ. The start rule Start → Q${ex.source.states.find(s=>s.initial).id} is supplied. Named variables keep uppercase terminals distinct and support more than 26 states.</p><details><summary>Normalized source states</summary><p>Multi-symbol and range labels are expanded before this exercise.</p><ul>${ex.source.states.map(s=>`<li>${s.id}: ${E(s.name)} → Q${s.id}${s.initial?' · initial':''}${s.final?' · final':''}</li>`).join('')}</ul></details><p>Enter variables as Q0, Q1, etc. Leave terminal and target blank for an empty production; leave only terminal blank for a λ transition.</p><div class="scroll"><table><tr><th>Source</th><th>Left variable</th><th>Terminal</th><th>Target variable</th><th>Check</th></tr>${ex.jobs.map(j=>`<tr><th>${E(j.description)}</th>${['left','terminal','target'].map(field=>`<td><input data-production="${j.key}" data-part="${field}" aria-label="${E(j.description+' '+field)}" value="${E(ex.answers[j.key][field])}"></td>`).join('')}<td data-production-result="${j.key}">${ex.checked.has(j.key)?'Correct':'Unchecked'}</td></tr>`).join('')}</table></div>${!ex.jobs.length?'<p>No transitions or final-state productions are needed. The supplied start rule represents the empty language.</p>':''}<p id="fa-grammar-selected"></p><div id="fa-grammar-actions" class="actions"></div><div id="fa-grammar-feedback" role="status"></div></div>`;
 const feedback=text=>$('#fa-grammar-feedback').textContent=text,selected=()=>{$('#fa-grammar-selected').textContent=session.selected?'Selected: '+ex.jobs.find(j=>j.key===session.selected).description:'No production selected.';};selected();
 $('#content').querySelectorAll('[data-production]').forEach(el=>{el.onfocus=()=>{session.selected=el.dataset.production;selected();};el.oninput=()=>{const key=el.dataset.production;ex.answers[key][el.dataset.part]=el.value;ex.checked.delete(key);$('#content').querySelector(`[data-production-result="${key}"]`).textContent='Unchecked';feedback('');};});
 const check=key=>{const r=ex.check(key);$('#content').querySelector(`[data-production-result="${key}"]`).textContent=r.correct?'Correct':'Check '+r.wrong.join(', ');return r.correct;},refresh=text=>{faGrammarPanel();feedback(text);};
 const actions=$('#fa-grammar-actions');if(ex.jobs.length)actions.append(button('Check selected production',()=>feedback(check(session.selected)?'Production is correct.':'Correct the indicated fields.'),'primary'),button('Do selected production',()=>{ex.fill(session.selected);refresh('Filled selected production.');}),button('Step productions',()=>{const key=ex.step();if(key)session.selected=key;refresh(key?'Filled one unchecked production.':'All productions are correct.');}),button('Complete productions',()=>{ex.finish();refresh('All productions are correct.');}),button('Check all productions',()=>{const results=ex.jobs.map(j=>check(j.key));feedback(results.every(Boolean)?'All productions are correct.':results.filter(x=>!x).length+' productions need correction.');}));
}

function grammarFAPanel(){
 const source=model(),signature=JSON.stringify(source.productions);let session=grammarFAExercises.get(source);
 try{if(!session||session.signature!==signature){session={signature,exercise:new GrammarFAExercise(source)};grammarFAExercises.set(source,session);}}catch(e){toolbar([]);$('#content').innerHTML=`<div class="panel"><h3>Grammar → FA</h3><p>${E(e.message)}</p></div>`;return;}
 const ex=session.exercise;session.selected??=ex.jobs[0].key;
 toolbar([['Open completed FA',()=>add(ex.export()),'primary'],['Reset transitions',()=>{ex.reset();grammarFAPanel();}]],'Translate each right-linear production into a path through the automaton.');
 $('#content').innerHTML=`<div class="panel"><h3>Guided right-linear grammar → FA</h3><p>Each variable has a state. A production A → word B goes from A to B reading word; A → word goes to the extra final state Accept. An empty word becomes a λ transition. Longer words are split into one-symbol transitions through intermediate states. The first production determines the initial state.</p><table><tr><th>State ID</th><th>Variable / role</th></tr>${ex.variables.map((v,i)=>`<tr><td>${i}</td><td>${E(v)}${i===0?' · initial':''}</td></tr>`).join('')}<tr><td>${ex.final}</td><td>Accept · final</td></tr></table><div class="scroll"><table><tr><th>Production</th><th>From state ID</th><th>Input word (blank for λ)</th><th>To state ID</th><th>Check</th></tr>${ex.jobs.map(j=>`<tr><th>${E(j.description)}</th>${['from','read','to'].map(part=>`<td><input data-fa-rule="${j.key}" data-fa-part="${part}" aria-label="Production ${Number(j.key)+1} ${part}" value="${E(ex.answers[j.key][part])}"></td>`).join('')}<td data-fa-result="${j.key}">${ex.checked.has(j.key)?'Correct':'Unchecked'}</td></tr>`).join('')}</table></div><p id="grammar-fa-selected"></p><div id="grammar-fa-actions" class="actions"></div><div id="grammar-fa-feedback" role="status"></div><svg id="grammar-fa-graph" viewBox="0 0 900 520" aria-label="Grammar automaton construction">${graphMarkup(ex.graph(),[],null)}</svg></div>`;
 const selected=()=>{$('#grammar-fa-selected').textContent='Selected production: '+(Number(session.selected)+1);};selected();const feedback=text=>$('#grammar-fa-feedback').textContent=text,drawResult=()=>$('#grammar-fa-graph').innerHTML=graphMarkup(ex.graph(),[],null);
 $('#content').querySelectorAll('[data-fa-rule]').forEach(el=>{el.onfocus=()=>{session.selected=el.dataset.faRule;selected();};el.oninput=()=>{const key=el.dataset.faRule;ex.answers[key][el.dataset.faPart]=el.value;ex.checked.delete(key);$('#content').querySelector(`[data-fa-result="${key}"]`).textContent='Unchecked';drawResult();feedback('');};});
 const check=key=>{const r=ex.check(key);$('#content').querySelector(`[data-fa-result="${key}"]`).textContent=r.correct?'Correct':'Check '+r.wrong.join(', ');return r.correct;},refresh=text=>{grammarFAPanel();feedback(text);};
 $('#grammar-fa-actions').append(button('Check selected transition',()=>{feedback(check(session.selected)?'Correct path added.':'Correct the indicated fields.');drawResult();},'primary'),button('Do selected transition',()=>{ex.fill(session.selected);refresh('Selected path added.');}),button('Step transitions',()=>{const key=ex.step();if(key!==null)session.selected=key;refresh(key!==null?'One unchecked path added.':'All paths are complete.');}),button('Complete transitions',()=>{ex.finish();refresh('All production paths are complete.');}),button('Check all transitions',()=>{const results=ex.jobs.map(j=>check(j.key));feedback(results.every(Boolean)?'All production paths are correct.':results.filter(x=>!x).length+' paths need correction.');drawResult();}));
}

function cfgPDAPanel(){
 const mode=tab==='Build PDA (LR)'?'lr':'ll',sessions=mode==='lr'?cfgPDALRExercises:cfgPDAExercises;const source=model(),signature=JSON.stringify(source.productions);let session=sessions.get(source);try{if(!session||session.signature!==signature){session={signature,exercise:new CFGPDAExercise(source,mode)};sessions.set(source,session);}}catch(e){toolbar([]);$('#content').innerHTML=`<div class="panel"><h3>CFG → PDA (${mode.toUpperCase()})</h3><p>${E(e.message)}</p></div>`;return;}
 const ex=session.exercise;session.selected??=ex.jobs[0].key;
 toolbar([['Open completed PDA',()=>add(ex.export()),'primary'],['Reset PDA construction',()=>{ex.reset();cfgPDAPanel();}]],mode==='ll'?'Build a nondeterministic top-down PDA from the grammar.':'Build a nondeterministic bottom-up PDA by shifting terminals and reducing productions.');
 $('#content').innerHTML=`<div class="panel"><h3>Guided CFG → PDA (${mode.toUpperCase()})</h3>${mode==='lr'?`<p>State 0 initializes the stack with ${E(ex.bottom)}. State 1 shifts input terminals onto the stack, or reduces a production A → w by reading λ, popping the reverse of w and pushing A. The stack top is on the left, so ab is popped as ba. An empty production pops nothing and pushes its left variable. State 2 accepts after popping the start variable followed by ${E(ex.bottom)}, with all input consumed. Use final-state acceptance. This is a nondeterministic bottom-up construction, not a deterministic LR parsing table.</p>`:`<p>State 0 initializes the stack, state 1 expands productions and matches terminals, and state 2 accepts. The stack top is on the left. Initialization replaces the simulator’s Z with the start variable followed by ${E(ex.bottom)}, a protected bottom marker. Each A → w expansion reads λ, pops A and pushes w. Matching a terminal reads and pops that terminal. Acceptance pops only ${E(ex.bottom)}; input must also be consumed. Use final-state acceptance when running the result.</p>`}<p>Enter state IDs 0, 1 or 2. Blank fields represent λ.</p><div class="scroll"><table><tr><th>Purpose</th><th>From</th><th>To</th><th>Read</th><th>Pop</th><th>Push</th><th>Check</th></tr>${ex.jobs.map(j=>`<tr><th>${E(j.description)}</th>${['from','to','read','pop','push'].map(part=>`<td><input data-pda-rule="${j.key}" data-pda-part="${part}" aria-label="Transition ${Number(j.key)+1} ${part}" value="${E(ex.answers[j.key][part])}"></td>`).join('')}<td data-pda-result="${j.key}">${ex.checked.has(j.key)?'Correct':'Unchecked'}</td></tr>`).join('')}</table></div><p id="cfg-pda-selected"></p><div id="cfg-pda-actions" class="actions"></div><div id="cfg-pda-feedback" role="status"></div><svg id="cfg-pda-graph" viewBox="0 0 900 520" aria-label="CFG PDA construction">${graphMarkup(ex.graph(),[],null)}</svg></div>`;
 const selected=()=>$('#cfg-pda-selected').textContent='Selected: '+ex.jobs.find(j=>j.key===session.selected).description;selected();const feedback=text=>$('#cfg-pda-feedback').textContent=text,drawResult=()=>$('#cfg-pda-graph').innerHTML=graphMarkup(ex.graph(),[],null);
 $('#content').querySelectorAll('[data-pda-rule]').forEach(el=>{el.onfocus=()=>{session.selected=el.dataset.pdaRule;selected();};el.oninput=()=>{const key=el.dataset.pdaRule;ex.answers[key][el.dataset.pdaPart]=el.value;ex.checked.delete(key);$('#content').querySelector(`[data-pda-result="${key}"]`).textContent='Unchecked';drawResult();feedback('');};});
 const check=key=>{const r=ex.check(key);$('#content').querySelector(`[data-pda-result="${key}"]`).textContent=r.correct?'Correct':'Check '+r.wrong.join(', ');return r.correct;},refresh=text=>{cfgPDAPanel();feedback(text);};
 $('#cfg-pda-actions').append(button('Check selected PDA transition',()=>{feedback(check(session.selected)?'Correct transition added.':'Correct the indicated fields.');drawResult();},'primary'),button('Do selected PDA transition',()=>{ex.fill(session.selected);refresh('Selected transition added.');}),button('Step PDA construction',()=>{const key=ex.step();if(key!==null)session.selected=key;refresh(key!==null?'One transition added.':'All transitions complete.');}),button('Complete PDA construction',()=>{ex.finish();refresh('All PDA transitions are complete.');}),button('Check all PDA transitions',()=>{const results=ex.jobs.map(j=>check(j.key));feedback(results.every(Boolean)?'All PDA transitions are correct.':results.filter(x=>!x).length+' transitions need correction.');drawResult();}));
}

function lambdaExercisePanel(){
 const source=model(),signature=JSON.stringify(source.productions);let session=lambdaExercises.get(source);try{if(!session||session.signature!==signature){session={signature,exercise:new LambdaExercise(source)};lambdaExercises.set(source,session);}}catch(e){toolbar([]);$('#content').innerHTML=`<div class="panel"><h3>Lambda removal</h3><p>${E(e.message)}</p></div>`;return;}const ex=session.exercise;
 toolbar([['Open transformed grammar',()=>add(ex.export()),'primary'],['Reset lambda exercise',()=>{ex.reset();lambdaExercisePanel();}]],'Find nullable variables, then add the alternatives obtained by omitting nullable occurrences.');
 $('#content').innerHTML=`<div class="panel"><h3>Nullable variables and lambda removal</h3><pre>${E(G.grammarText(source.productions))}</pre><p>A variable is nullable if it derives the empty word. Include variables reached through chains of nullable productions. Enter variable names separated by commas, or ∅ for an empty set.</p><label class="field"><span>Nullable variables</span><input id="lambda-set" value="${E(ex.setAnswer)}"></label><div id="lambda-set-actions" class="actions"></div><div id="lambda-set-feedback" role="status"></div><details><summary>Nullable discovery rounds (hint)</summary><ol>${ex.rounds.map(round=>`<li>${E(round.join(', '))}</li>`).join('')}</ol>${!ex.rounds.length?'No nullable variables.':''}</details><p>For each production, keep its original nonempty right side and add every distinct alternative formed by omitting nullable variable occurrences. Remove empty productions except ${E(ex.start)} → λ when the start variable is nullable; this preserves the empty word. This convention may retain the start variable on right sides. The empty-language fallback on export uses ${E(ex.start)} → ${E(ex.start)} if there are no productions.</p><label class="field"><span>Transformed productions</span><textarea id="lambda-productions" rows="9">${E(ex.productionAnswer)}</textarea></label><div id="lambda-production-actions" class="actions"></div><div id="lambda-production-feedback" role="status"></div></div>`;
 $('#lambda-set').oninput=()=>{ex.setAnswer=$('#lambda-set').value;ex.setChecked=false;$('#lambda-set-feedback').textContent='';$('#lambda-production-feedback').textContent='Recheck the nullable set before checking productions.';};
 $('#lambda-productions').oninput=()=>{ex.productionAnswer=$('#lambda-productions').value;$('#lambda-production-feedback').textContent='';};
 const checkSet=()=>{const r=ex.checkSet();$('#lambda-set-feedback').textContent=r.correct?'Nullable set is correct.':r.error||`Missing: ${r.missing.join(', ')||'none'}; extra: ${r.extra.join(', ')||'none'}.`;};
 $('#lambda-set-actions').append(button('Check nullable set',checkSet,'primary'),button('Fill nullable set',()=>{ex.fillSet();$('#lambda-set').value=ex.setAnswer;checkSet();}));
 $('#lambda-production-actions').append(button('Check transformed productions',()=>{const r=ex.checkProductions();$('#lambda-production-feedback').textContent=r.correct?'Transformed productions are correct.':r.error||`Missing: ${G.grammarText(r.missing)||'none'}; extra: ${G.grammarText(r.extra)||'none'}.`;},'primary'),button('Complete transformed productions',()=>{ex.fillProductions();$('#lambda-productions').value=ex.productionAnswer;$('#lambda-production-feedback').textContent='Filled the transformed productions.';}));
}

function unitExercisePanel(){
 const source=model(),signature=JSON.stringify(source.productions);let session=unitExercises.get(source);try{if(!session||session.signature!==signature){session={signature,exercise:new UnitExercise(source)};unitExercises.set(source,session);}}catch(e){toolbar([]);$('#content').innerHTML=`<div class="panel"><h3>Unit removal</h3><p>${E(e.message)}</p></div>`;return;}const ex=session.exercise;session.selected??=ex.variables[0];
 toolbar([['Open grammar without unit rules',()=>add(ex.export()),'primary'],['Reset unit exercise',()=>{ex.reset();unitExercisePanel();}]],'Find every variable reachable through unit productions, including the starting variable itself.');
 const graph=A.machine();ex.variables.forEach(v=>{const s=A.state(graph);s.name=v;s.initial=false;});ex.edges.forEach(p=>A.edge(graph,ex.variables.indexOf(p.left),ex.variables.indexOf(p.right),'unit'));A.layout(graph);
 $('#content').innerHTML=`<div class="panel"><h3>Unit dependencies and removal</h3><pre>${E(G.grammarText(source.productions))}</pre><p>A unit production has a single variable on its right side. For each variable A, list A itself and every variable reachable through any number of unit productions. Cycles do not add duplicate members.</p><details><summary>Unit dependency graph (hint)</summary><svg viewBox="0 0 900 520" aria-label="Unit dependency graph">${graphMarkup(graph,[],null)}</svg></details><table><tr><th>Variable</th><th>Reachable variables</th><th>Check</th></tr>${ex.variables.map(v=>`<tr><th>${E(v)}</th><td><input data-unit-variable="${E(v)}" aria-label="Unit dependencies for ${E(v)}" value="${E(ex.answers[v])}"></td><td data-unit-result="${E(v)}">Unchecked</td></tr>`).join('')}</table><p id="unit-selected"></p><div id="unit-set-actions" class="actions"></div><div id="unit-set-feedback" role="status"></div><p>For every reachable variable B, copy each non-unit production B → w as A → w. Remove all unit productions. Preserve empty productions. If the start variable has no resulting rule, export uses a nonterminating rule such as ${E(ex.start)} → a${E(ex.start)} to represent the empty language without changing the start symbol.</p><label class="field"><span>Replacement productions</span><textarea id="unit-productions" rows="9">${E(ex.productionAnswer)}</textarea></label><div id="unit-production-actions" class="actions"></div><div id="unit-production-feedback" role="status"></div></div>`;
 const select=v=>{session.selected=v;$('#unit-selected').textContent='Selected variable: '+v;};select(session.selected);
 $('#content').querySelectorAll('[data-unit-variable]').forEach(el=>{el.onfocus=()=>select(el.dataset.unitVariable);el.oninput=()=>{ex.answers[el.dataset.unitVariable]=el.value;$('#content').querySelector(`[data-unit-result="${el.dataset.unitVariable}"]`).textContent='Unchecked';$('#unit-set-feedback').textContent='';$('#unit-production-feedback').textContent='';};});
 const check=v=>{const r=ex.check(v);$('#content').querySelector(`[data-unit-result="${v}"]`).textContent=r.correct?'Correct':r.error||`Missing: ${r.missing.join(', ')||'none'}; extra: ${r.extra.join(', ')||'none'}`;return r.correct;};
 $('#unit-set-actions').append(button('Check selected dependency',()=>{$('#unit-set-feedback').textContent=check(session.selected)?'Dependency set is correct.':'Correct the indicated set.';},'primary'),button('Fill selected dependency',()=>{ex.fill(session.selected);$('#content').querySelector(`[data-unit-variable="${session.selected}"]`).value=ex.answers[session.selected];check(session.selected);}),button('Fill all dependencies',()=>{ex.fillAll();unitExercisePanel();ex.variables.forEach(check);}),button('Check all dependencies',()=>{$('#unit-set-feedback').textContent=ex.variables.map(check).every(Boolean)?'All dependencies are correct.':'Some dependency sets need correction.';}));
 $('#unit-productions').oninput=()=>{ex.productionAnswer=$('#unit-productions').value;$('#unit-production-feedback').textContent='';};
 $('#unit-production-actions').append(button('Check replacement productions',()=>{const r=ex.checkProductions();$('#unit-production-feedback').textContent=r.correct?'Replacement productions are correct.':r.error||`Missing: ${G.grammarText(r.missing)||'none'}; extra: ${G.grammarText(r.extra)||'none'}.`;},'primary'),button('Complete replacement productions',()=>{ex.fillProductions();$('#unit-productions').value=ex.productionAnswer;$('#unit-production-feedback').textContent='Filled replacement productions.';}));
}

function uselessExercisePanel(){
 const source=model(),signature=JSON.stringify(source.productions);let session=uselessExercises.get(source);try{if(!session||session.signature!==signature){session={signature,exercise:new UselessExercise(source)};uselessExercises.set(source,session);}}catch(e){toolbar([]);$('#content').innerHTML=`<div class="panel"><h3>Useless-production removal</h3><p>${E(e.message)}</p></div>`;return;}const ex=session.exercise;
 toolbar([['Open useful grammar',()=>add(ex.export()),'primary'],['Reset useful-variable exercise',()=>{ex.reset();uselessExercisePanel();}]],'Find generating variables first; then find reachability after removing non-generating productions.');
 $('#content').innerHTML=`<div class="panel"><h3>Useful variables and production removal</h3><pre>${E(G.grammarText(source.productions))}</pre><p>Generating variables derive a terminal word, including λ. Remove every production involving a non-generating variable. Then follow variable dependencies from ${E(ex.start)} in the remaining grammar. Include ${E(ex.start)} itself in the reachable set even when it has no remaining rules.</p>${['generating','reachable'].map(kind=>`<label class="field"><span>${kind==='generating'?'Generating variables':'Reachable variables after pruning'}</span><input id="useful-${kind}" value="${E(ex.answers[kind])}"></label><div id="useful-${kind}-actions" class="actions"></div><div id="useful-${kind}-feedback" role="status"></div>`).join('')}<details><summary>Discovery and dependency hints</summary><h4>Generating rounds</h4><ol>${ex.rounds.map(r=>'<li>'+E(r.join(', '))+'</li>').join('')}</ol><h4>Productions after removing non-generating variables</h4><pre>${E(G.grammarText(ex.productive)||'No productions remain.')}</pre><h4>Remaining variable dependencies</h4><ul>${ex.productive.flatMap(p=>[...new Set([...p.right].filter(G.variable))].map(v=>'<li>'+E(p.left+' → '+v)+'</li>')).join('')}</ul></details><p>Keep only productions whose left variable is reachable in the pruned grammar. Enter one production per line. If none remain, leave the answer blank. Export represents that empty language with a nonterminating placeholder such as ${E(ex.start)} → a${E(ex.start)} because the document editor requires a start rule; that placeholder is intentionally non-generating.</p><label class="field"><span>Remaining productions</span><textarea id="useful-productions" rows="9">${E(ex.productionAnswer)}</textarea></label><div id="useful-production-actions" class="actions"></div><div id="useful-production-feedback" role="status"></div></div>`;
 for(const kind of ['generating','reachable']){const input=$('#useful-'+kind),check=()=>{const r=ex.check(kind);$('#useful-'+kind+'-feedback').textContent=r.correct?'Variable set is correct.':r.error||`Missing: ${r.missing.join(', ')||'none'}; extra: ${r.extra.join(', ')||'none'}.`;};input.oninput=()=>{ex.answers[kind]=input.value;$('#useful-'+kind+'-feedback').textContent='';$('#useful-production-feedback').textContent='';};$('#useful-'+kind+'-actions').append(button('Check '+kind+' variables',check,'primary'),button('Fill '+kind+' variables',()=>{ex.fill(kind);input.value=ex.answers[kind];check();}));}
 $('#useful-productions').oninput=()=>{ex.productionAnswer=$('#useful-productions').value;$('#useful-production-feedback').textContent='';};
 $('#useful-production-actions').append(button('Check remaining productions',()=>{const r=ex.checkProductions();$('#useful-production-feedback').textContent=r.correct?'Remaining productions are correct.':r.error||`Missing: ${G.grammarText(r.missing)||'none'}; extra: ${G.grammarText(r.extra)||'none'}.`;},'primary'),button('Complete remaining productions',()=>{ex.fillProductions();$('#useful-productions').value=ex.productionAnswer;$('#useful-production-feedback').textContent='Filled remaining productions.';}));
}

function cnfExercisePanel(){
 const source=model(),signature=JSON.stringify(source.productions);let session=cnfExercises.get(source);try{if(!session||session.signature!==signature){session={signature,exercise:new CNFExercise(source)};cnfExercises.set(source,session);}}catch(e){toolbar([]);$('#content').innerHTML=`<div class="panel"><h3>CNF construction</h3><p>${E(e.message)}</p></div>`;return;}const ex=session.exercise,terminals=ex.terminals(),long=ex.longRules();
 toolbar([['Open CNF grammar',()=>add(ex.export()),'primary'],['Undo CNF step',()=>{ex.undo();cnfExercisePanel();}],['Reset CNF construction',()=>{ex.reset();cnfExercisePanel();}]],'Replace terminals in compound right sides, then split long right sides into pairs.');
 $('#content').innerHTML=`<div class="panel"><h3>Interactive Chomsky normal form</h3><p>Preparation automatically isolates the start variable when needed and removes lambda, unit and useless productions. The exercises in the other tabs let you practice those stages separately. Here, choose unused uppercase variables for terminal replacement and binarization. Start variable: ${E(ex.start)}.</p><details><summary>Automatic preparation stages</summary>${ex.preparation.map(stage=>`<h4>${E(stage.label)}</h4><pre>${E(G.grammarText(stage.productions)||'No productions.')}</pre>`).join('')}</details>${ex.emptyLanguage?'<p>The source generates no words. A non-generating binary grammar preserves that empty language while satisfying the CNF shape.</p>':''}<h4>Current productions</h4><ol start="1">${ex.productions.map(p=>'<li>'+E(G.grammarText([p]))+'</li>').join('')}</ol>${terminals.length?`<label class="field"><span>Terminal to replace</span><select id="cnf-terminal">${terminals.map(c=>`<option value="${E(c)}">${E(c)}</option>`).join('')}</select></label>`:long.length?`<label class="field"><span>Production to split</span><select id="cnf-rule">${long.map(p=>`<option value="${p.index}">${E(G.grammarText([p]))}</option>`).join('')}</select></label>`:'<p>Construction complete: A → BC, A → a, and optionally the start variable → λ.</p>'}${terminals.length||long.length?'<label class="field"><span>New variable</span><input id="cnf-variable" maxlength="1" placeholder="Unused uppercase letter"></label>':''}<div id="cnf-actions" class="actions"></div><div id="cnf-feedback" role="status"></div><h4>Construction steps</h4><ol>${ex.steps.map(step=>'<li>'+E(step)+'</li>').join('')}</ol></div>`;
 const act=fn=>()=>{try{fn();cnfExercisePanel();}catch(e){$('#cnf-feedback').textContent=e.message;}};
 if(terminals.length)$('#cnf-actions').append(button('Replace selected terminal',act(()=>ex.replaceTerminal($('#cnf-terminal').value,$('#cnf-variable').value.trim())),'primary'));
 else if(long.length)$('#cnf-actions').append(button('Split selected production',act(()=>ex.split(Number($('#cnf-rule').value),$('#cnf-variable').value.trim())),'primary'));
 if(!ex.ready())$('#cnf-actions').append(button('Step CNF construction',act(()=>ex.step())),button('Complete CNF construction',act(()=>ex.finish())));
}
